-- ===========================================================================
-- 11-timesheet-sample-data.sql
--
-- Sample data for the three level test case:
--   12 customers, 62 engagements, 1052 time entries.
--
-- Every customer has several engagements and every engagement has a dozen or
-- more time entries, because a search demonstration over three rows proves
-- nothing: the point is to see a customer search return items at all three
-- levels and to see them ranked sensibly against each other.
--
-- The Contoso, Fabrikam, Northwind, Tailspin and Woodgrove entries at the top
-- of each table are hand written and are the ones to demonstrate with; the
-- remainder are generated to give the index realistic volume and spread.
--
-- 8 time entries are soft deleted on purpose (IsDeleted = 1). They give
-- deploy/Compare-SourceToIndex.ps1 something to find after a second push, which
-- is how the direct push path's one real weakness is shown rather than merely
-- described. See docs/HIERARCHY-TEST-CASE.md.
--
-- Idempotent: deletes and reinserts these exact ID ranges and touches nothing
-- else. Run 10-timesheet-source.sql first.
-- ===========================================================================

USE [Ops];
GO

SET NOCOUNT ON;
GO

-- Children first, so the foreign keys never block the reset.
DELETE FROM dbo.TimeEntries WHERE TimeEntryId BETWEEN 5001 AND 9999;
DELETE FROM dbo.Engagements WHERE EngagementId BETWEEN 101 AND 999;
DELETE FROM dbo.Customers   WHERE CustomerId   BETWEEN 1 AND 99;
GO

