VALUES
 (5001, 101, N'Priya Raman', N'priya.raman@consultco.com', '2026-08-03', 7.50, 1, N'Delivery',
  N'Migrated the customer master domain into the lakehouse bronze layer and reconciled row counts against the source. Two tables differed by a handful of rows, traced to a nightly purge job nobody had documented.',
