  DATEADD(HOUR, -6, SYSUTCDATETIME()), 0),
 (5007, 101, N'Priya Raman', N'priya.raman@consultco.com', '2026-08-10', 8.00, 1, N'Delivery',
  N'Second migration wave: three domains lifted, two clean, one blocked on a column holding free text customer complaints that needs a retention decision before it can move.',
  DATEADD(HOUR, -7, SYSUTCDATETIME()), 0),
 (5008, 101, N'Jonas Berg', N'jonas.berg@consultco.com', '2026-08-11', 4.00, 0, N'Documentation',
  N'Wrote up the migration runbook and the rollback procedure. Not billable, agreed with Rachel as part of the fixed price handover.',
  DATEADD(HOUR, -8, SYSUTCDATETIME()), 1),
 (5009, 101, N'Yuki Tanaka', N'yuki.tanaka@consultco.com', '2026-08-12', 6.50, 1, N'Delivery',
