  DATEADD(HOUR, -9, SYSUTCDATETIME()), 0),
 (5010, 101, N'Priya Raman', N'priya.raman@consultco.com', '2026-08-14', 7.50, 1, N'Delivery',
  N'Cut over the customer master domain in production. Ran the reconciliation suite immediately afterwards, all green. The Contoso reporting team confirmed their dashboards were correct by mid afternoon.',
  DATEADD(HOUR, -10, SYSUTCDATETIME()), 0),
 (5011, 102, N'Hassan Malik', N'hassan.malik@consultco.com', '2026-04-07', 6.00, 1, N'Advisory',
  N'Reviewed the payment gateway failover configuration. The secondary region is provisioned but has never been exercised under load; failover has only ever been tested with synthetic traffic at two percent of peak.',
