 (5012, 102, N'Hassan Malik', N'hassan.malik@consultco.com', '2026-04-08', 7.00, 1, N'Advisory',
  N'Traced the settlement path end to end looking for idempotency gaps. Found one: a retry after a gateway timeout can produce a duplicate settlement record if the original request actually succeeded.',
  DATEADD(HOUR, -12, SYSUTCDATETIME()), 0),
 (5013, 102, N'Grace Whitfield', N'grace.whitfield@consultco.com', '2026-04-14', 5.50, 1, N'Workshop',
