-- ---------------------------------------------------------------------------
-- Verification
-- ---------------------------------------------------------------------------

-- 1. What was loaded, per level.
SELECT 'Customers' AS level, COUNT(*) AS total, SUM(CASE WHEN IsDeleted = 1 THEN 1 ELSE 0 END) AS soft_deleted FROM dbo.Customers
UNION ALL
SELECT 'Engagements', COUNT(*), SUM(CASE WHEN IsDeleted = 1 THEN 1 ELSE 0 END) FROM dbo.Engagements
UNION ALL
SELECT 'TimeEntries', COUNT(*), SUM(CASE WHEN IsDeleted = 1 THEN 1 ELSE 0 END) FROM dbo.TimeEntries;

-- 2. Every customer must have engagements, and every engagement time entries.
--    Expect zero rows: an empty level would make the hierarchy demonstration
--    fall flat for that customer.
SELECT c.CustomerName, 'no engagements' AS problem
FROM   dbo.Customers AS c
WHERE  c.IsDeleted = 0
  AND  NOT EXISTS (SELECT 1 FROM dbo.Engagements e WHERE e.CustomerId = c.CustomerId AND e.IsDeleted = 0)
UNION ALL
SELECT e.EngagementName, 'no time entries'
FROM   dbo.Engagements AS e
WHERE  e.IsDeleted = 0
  AND  NOT EXISTS (SELECT 1 FROM dbo.TimeEntries t WHERE t.EngagementId = e.EngagementId AND t.IsDeleted = 0);

-- 3. The roll up a Copilot answer should be able to reproduce from the indexed
--    items alone, without doing arithmetic across items.
SELECT  c.CustomerName,
        COUNT(DISTINCT e.EngagementId) AS engagements,
        COUNT(te.TimeEntryId)          AS time_entries,
        SUM(te.Hours)                  AS total_hours,
        SUM(CASE WHEN te.Billable = 1 THEN te.Hours ELSE 0 END) AS billable_hours
FROM    dbo.Customers   AS c
JOIN    dbo.Engagements AS e  ON e.CustomerId = c.CustomerId  AND e.IsDeleted = 0
LEFT JOIN dbo.TimeEntries AS te ON te.EngagementId = e.EngagementId AND te.IsDeleted = 0
WHERE   c.IsDeleted = 0
GROUP BY c.CustomerName
ORDER BY total_hours DESC;
GO
